css:
.mp-page {
  height: 100dvh;
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: clamp(10px, 1.5vh, 18px);
  padding: clamp(18px, 2.4vw, 36px);
  background: var(--mp-panel);
  color: var(--mp-ink);
  font-family: var(--mp-font-sans);
  font-size: clamp(13px, 1vw, 16px);
}
.mp-page > * { min-width: 0; }
.mp-head { display: grid; gap: 6px; }
.mp-eyebrow { margin: 0; font-size: 12px; font-weight: 600; letter-spacing: .16em; color: var(--mp-faint); text-transform: uppercase; }
.mp-title { margin: 0; font-size: clamp(24px, 2.7vw, 40px); line-height: 1.12; letter-spacing: -0.01em; font-weight: 700; }
.mp-sub { margin: 0; max-width: 62ch; font-size: clamp(13px, 1.05vw, 16px); line-height: 1.6; color: var(--mp-muted); }

.mp-body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); gap: clamp(16px, 2.4vw, 34px); }

.mp-figure { min-height: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto; gap: 8px; padding: clamp(12px, 1.4vw, 20px); border: 1px solid var(--mp-border); border-radius: 20px; background: var(--mp-raised); }
.mp-grid { width: 100%; height: 100%; min-height: 0; }
.mp-grid-lines line { stroke: var(--mp-border); stroke-width: 1; }
.mp-axes line { stroke: var(--mp-border-strong); stroke-width: 1; }
.mp-unit { fill: none; stroke: var(--mp-faint); stroke-width: 1; stroke-dasharray: 4 4; }
.mp-image { opacity: 0; transition: opacity 200ms ease; }
.mp-image-fill { fill: var(--mp-raised); stroke: var(--mp-border-strong); stroke-width: 1; }
.mp-vec-image { stroke: var(--mp-ink); stroke-width: 2; }
.mp-vec { stroke: var(--mp-ink); stroke-width: 2; }
.mp-svg-label { fill: var(--mp-muted); font-family: var(--mp-font-mono); font-size: 12px; }
.mp-svg-axis { fill: var(--mp-faint); font-family: var(--mp-font-mono); font-size: 12px; }
.mp-caption { margin: 0; font-size: 12px; line-height: 1.6; color: var(--mp-muted); }

.mp-derive { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 10px; }
.mp-hint-line { margin: 0; font-size: 13px; line-height: 1.6; color: var(--mp-faint); }
.mp-steps { margin: 0; padding: 0; list-style: none; display: grid; align-content: start; gap: 8px; overflow: hidden; }
.mp-steps li { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 10px; padding: 9px 12px; border: 1px solid var(--mp-border); border-left: 2px solid var(--mp-border-strong); border-radius: 10px; background: var(--mp-panel); }
.mp-steps li[data-mp-state="pending"] { display: none; }
.mp-step-no { font-family: var(--mp-font-mono); font-size: 12px; color: var(--mp-faint); padding-top: 2px; }
.mp-step-title { margin: 0 0 2px; font-size: 13px; font-weight: 600; }
.mp-step-body { margin: 0; font-size: 13px; line-height: 1.6; color: var(--mp-muted); }
.mp-hint-line { display: none; }
.mp-page[data-mp-step="0"] .mp-hint-line { display: block; }

.mp-compare { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; padding-top: 10px; border-top: 1px solid var(--mp-border); }
.mp-mat-block { display: grid; gap: 4px; min-width: 0; }
.mp-label { margin: 0; font-size: 11px; font-weight: 600; letter-spacing: .12em; color: var(--mp-faint); }
.mp-mat { display: inline-grid; grid-template-columns: repeat(2, minmax(26px, auto)); gap: 2px 10px; justify-self: start; padding: 2px 8px; border-left: 1px solid var(--mp-ink); border-right: 1px solid var(--mp-ink); font-family: var(--mp-font-mono); font-size: clamp(13px, 1.1vw, 16px); line-height: 1.5; }
.mp-mat b { font-weight: 600; text-align: center; }
.mp-mat-block[data-mp-layer="rs"] { opacity: 0; visibility: hidden; transition: opacity 200ms ease; }
.mp-page[data-mp-step="5"] .mp-mat-block[data-mp-layer="rs"] { opacity: 1; visibility: visible; }
.mp-page[data-mp-step="4"] .mp-image,
.mp-page[data-mp-step="5"] .mp-image { opacity: 1; }

.mp-foot { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 10px 16px; font-size: 12px; color: var(--mp-muted); }
.mp-source { margin: 0; max-width: 58ch; }
.mp-controls { display: flex; flex-wrap: wrap; gap: 8px; }
.mp-btn { min-height: 40px; padding: 0 16px; border: 1px solid var(--mp-border-strong); border-radius: 12px; background: var(--mp-panel); color: var(--mp-ink); font: inherit; font-size: 14px; cursor: pointer; }
.mp-btn:hover { border-color: var(--mp-ink); }
.mp-btn-primary { background: var(--mp-invert); color: var(--mp-invert-ink); border-color: var(--mp-invert); }
.mp-btn:focus-visible { outline: 2px solid var(--mp-ink); outline-offset: 2px; }

html[data-mp-reduced-motion="true"] .mp-page,
html[data-mp-reduced-motion="true"] .mp-page * { transition: none !important; animation: none !important; }
@media (prefers-reduced-motion: reduce) {
  .mp-page, .mp-page * { transition: none; animation: none; }
}
@media (max-width: 900px) {
  .mp-body { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(120px, 0.7fr) minmax(0, 1fr); }
  .mp-caption { display: none; }
}

js:
(function () {
  var STATES = ['idle', 'columns', 'combine', 'compose', 'compute', 'compared'];
  var MAX = 5;
  var root = document.querySelector('.mp-page');
  if (!root) { return; }
  var items = root.querySelectorAll('li[data-mp-step]');
  var stepBtn = root.querySelector('[data-mp-action="step"]');
  var prevBtn = root.querySelector('[data-mp-action="prev"]');
  var compareBtn = root.querySelector('[data-mp-action="compare"]');
  var step = 0;

  function render() {
    root.dataset.mpStep = String(step);
    root.dataset.mpState = STATES[step];
    for (var i = 0; i < items.length; i += 1) {
      var n = Number(items[i].getAttribute('data-mp-step'));
      items[i].setAttribute('data-mp-state', n <= step ? 'shown' : 'pending');
    }
  }

  function emit() {
    window.MockFinal.emit('interaction', { id: 'matrix-derive', step: step, state: root.getAttribute('data-mp-state') });
  }

  if (stepBtn) {
    stepBtn.addEventListener('click', function () {
      if (step < MAX) {
        step += 1;
        render();
        emit();
      }
    });
  }
  if (prevBtn) {
    prevBtn.addEventListener('click', function () {
      if (step > 0) {
        step -= 1;
        render();
        emit();
      }
    });
  }
  if (compareBtn) {
    compareBtn.addEventListener('click', function () {
      if (step < MAX) {
        step = MAX;
        render();
        emit();
      }
    });
  }

  if (typeof window.MockFinal.onHostMessage === 'function') {
    window.MockFinal.onHostMessage(function (msg) {
      if (msg && msg.type === 'theme') { render(); }
    });
  }

  render();
  window.MockFinal.ready({ title: '矩阵变换：列、复合与顺序' });
})();
